#include HEADER
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <random>
int main(int argc,char**argv){if(argc!=5)return 2;std::size_t n=std::strtoull(argv[1],nullptr,10);int length=std::atoi(argv[2]),kind=std::atoi(argv[3]),reps=std::atoi(argv[4]);std::mt19937_64 rng(123);std::vector<std::string> words(n,std::string(length,'a'));for(std::size_t i=0;i<n;++i){for(int j=0;j<length;++j)words[i][j]=static_cast<char>((kind==3?0:'a')+rng()%(kind==3?256:(kind==4?2:26)));if(kind==1)for(int j=0;j<length/2;++j)words[i][j]='a';if(kind==2)words[i]=words[i%16];}
std::uint64_t sum=0;auto t=std::chrono::steady_clock::now();for(int rep=0;rep<reps;++rep){Trie trie;for(const auto&w:words)trie.insert(w);for(const auto&w:words)sum+=trie.count(w);for(std::size_t i=0;i<n;i+=2)sum+=trie.erase(words[i]);sum+=trie.distinct_size();}auto e=std::chrono::steady_clock::now();std::cout<<std::chrono::duration<double,std::milli>(e-t).count()<<' '<<sum<<'\n';}
